mapper.sql:
WITH objRec AS( SELECT tmp1.PROD_ID, tmp1.VDATE, IFNULL(tmp1.actEndMDate,tmp1.MDate) MDATE, STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') as holdDate FROM ( SELECT A.PROD_ID, A.VDATE, A.MDATE, B.MDATE AS actEndMDate, B.STATUS, ROW_NUMBER() over( partition by A.PROD_ID ORDER BY B.UPDATE_TIME DESC) AS endStatusNo FROM CHB_PRD_BASEINFO A LEFT JOIN CHB_PRD_END_SUB B ON A.PROD_ID = B.PROD_ID WHERE A.STATUS != 'D'
#{orgCode,jdbcType=VARCHAR}
AND A.ISSUING_STATUS != '02' AND A.FPROD_ID is null AND STR_TO_DATE(DATE_FORMAT(A.VDATE, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') ) tmp1 WHERE endStatusNo = 1 AND IFNULL(tmp1.STATUS,'01') != '03' AND STR_TO_DATE(DATE_FORMAT(IFNULL(actEndMDate,MDATE), '%Y-%m-%d'), '%Y-%m-%d') > STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') )
